package io.github.linker2k.myembro.engine.texture

import kotlinx.serialization.json.*
import kotlin.math.floor

/** Measured synthetic-corpus presets, NOT a guarantee for arbitrary photos.
 * Data is generated by :engine:sweepThreadTextureRaster, never hand-tuned to bypass a gate.
 * Photo correction/hoop width policy remains shared; only texture sampling uses physical pitch.
 */
object TextureRasterPolicy {
    private val data = Json.parseToJsonElement(requireNotNull(javaClass.getResourceAsStream("/texture/raster-policy.json"))
        .bufferedReader().use { it.readText() }).jsonObject
    val normalMmPerPixel = data.getValue("normalMmPerPixel").jsonPrimitive.double
    val coarseMmPerPixel = data.getValue("coarseMmPerPixel").jsonArray.map { it.jsonPrimitive.double }
    val fineMinimumMmPerPixel = data.getValue("fineMinimumMmPerPixel").jsonPrimitive.double
    val allPassingPitchesMmPerPixel = data.getValue("allPassingPitchesMmPerPixel").jsonArray.map { it.jsonPrimitive.double }
    val blockGuidanceKo = data.getValue("onBlock").jsonPrimitive.content

    /** Existing detail indices: coarse / normal / fine. Fine remains at the measured normal floor.
     * The second measured coarse choice is also exposed in [coarseMmPerPixel]. No unmeasured pitch.
     */
    fun pitchForDetail(detail: Int): Double = when (detail.coerceIn(0, 2)) {
        0 -> coarseMmPerPixel.first()
        1 -> normalMmPerPixel
        else -> fineMinimumMmPerPixel
    }
    fun edge(frameMm: Double, pitchMmPerPixel: Double = normalMmPerPixel): Int {
        require(frameMm.isFinite() && frameMm > 0)
        require(pitchMmPerPixel >= fineMinimumMmPerPixel && pitchMmPerPixel in allPassingPitchesMmPerPixel) { "Unmeasured or too-fine texture pitch" }
        // Floor: actual frameMm / pixels is >= requested pitch, including nondivisible sizes.
        return floor(frameMm / pitchMmPerPixel).toInt().coerceAtLeast(1)
    }
}
